// ─── MAIN APP ─────────────────────────────────────────────────────────────────
export default function App() {
  const [screen,setScreen]             = useState("splash");
  const [tab,setTab]                   = useState("passport");
  const [user,setUser]                 = useState(null);
  const [userId]                       = useState(()=>`u_${Date.now()}_${Math.random().toString(36).slice(2,7)}`);
  const [vendorStamps,setStamps]       = useState({});
  const [soloCompleted,setSolo]        = useState([]);
  const [votes,setVotes]               = useState({});
  const [uploads,setUploads]           = useState({});   // { taskId: dataURL }
  const [bonusPoints,setBonus]         = useState(0);   // points added back after redemption bonus
  const [redeemedPts,setRedeemed]      = useState(0);   // total points spent on prizes
  const [activePin,setActivePin]       = useState(null);
  const [activeCat,setActiveCat]       = useState(null);
  const [lastSuccess,setLast]          = useState(null);
  const [drawDone,setDrawDone]         = useState(false);
  const [leaderboard,setLeaderboard]   = useState([]);

  const rawPoints    = totalPts(vendorStamps, soloCompleted) + bonusPoints;
  const points       = Math.max(0, rawPoints - redeemedPts);
  const currentPrize = getPrize(points);

  // ── Leaderboard: load + poll ──────────────────────────────────────────────
  const loadLeaderboard = useCallback(async () => {
    try {
      const result = await window.storage.list("lb:", true);
      if(!result) return;
      const entries = await Promise.all(
        result.keys.map(async k => {
          try {
            const r = await window.storage.get(k, true);
            return r ? JSON.parse(r.value) : null;
          } catch { return null; }
        })
      );
      setLeaderboard(entries.filter(Boolean));
    } catch {}
  }, []);

  useEffect(() => {
    loadLeaderboard();
    const interval = setInterval(loadLeaderboard, 10000);
    return () => clearInterval(interval);
  }, [loadLeaderboard]);

  // ── Leaderboard: push own entry when points change ────────────────────────
  useEffect(() => {
    if(!user || points === 0) return;
    const entry = {
      id: userId,
      initials: getInitials(user.name),
      name: user.name,
      points,
      prize: getPrize(points),
      submitted: drawDone,
    };
    window.storage.set(`lb:${userId}`, JSON.stringify(entry), true).catch(()=>{});
  }, [user, points, drawDone, userId]);

  // ── Navigation helpers ────────────────────────────────────────────────────
  const openCat       = cat          => { setActiveCat(cat); setScreen("category"); };
  const openVendorPin = (cat,vendor) => {
    setActivePin({label:vendor.name,icon:cat.icon,pin:vendor.pin,earnedPts:vendor.points,targetId:vendor.id,type:"vendor"});
    setScreen("pin");
  };
  const openSoloPin = task => {
    // If task has upload and we received uploadData, store it then open pin
    if(task.hasUpload && task.uploadData) {
      setUploads(u => ({...u, [task.id]: task.uploadData}));
      setActivePin({label:task.label,icon:task.icon,pin:task.pin,earnedPts:task.points,targetId:task.id,type:"solo"});
      setScreen("pin");
      return;
    }
    // If task has upload and "GET STAMPED" pressed (uploadData already stored)
    if(task.hasUpload && !task.uploadData) {
      setActivePin({label:task.label,icon:task.icon,pin:task.pin,earnedPts:task.points,targetId:task.id,type:"solo"});
      setScreen("pin");
      return;
    }
    setActivePin({label:task.label,icon:task.icon,pin:task.pin,earnedPts:task.points,targetId:task.id,type:"solo",hasvote:task.hasvote});
    setScreen("pin");
  };
  const pinSuccess = voteData => {
    if(activePin.type==="vendor") setStamps(s=>({...s,[activePin.targetId]:true}));
    else {
      setSolo(c=>[...c,activePin.targetId]);
      if(voteData) setVotes(v=>({...v,[activePin.targetId]:`${voteData.cat}: ${voteData.pick}`}));
    }
    setLast({label:activePin.label,icon:activePin.icon,earnedPts:activePin.earnedPts});
    setScreen("success");
  };
  const claimSuccess = () => {
    // Deduct prize points
    const prize = getPrize(points);
    if(prize) setRedeemed(r => r + prize.pts);
    setLast({prizeMode:true, prize: getPrize(points)});
    setScreen("prizeClaimed");
  };

  const showMainTabs = screen==="main";

  // ── Screens ───────────────────────────────────────────────────────────────
  if(screen==="splash")      return <SplashScreen onEnter={()=>setScreen("register")}/>;
  if(screen==="register")    return <RegisterScreen onRegister={u=>{setUser(u);setScreen("main");}}/>;

  if(screen==="main") return (
    <div style={{position:"relative",minHeight:"100vh",background:BG}}>
      {tab==="passport"   && <PassportTab user={user} points={points} vendorStamps={vendorStamps} soloCompleted={soloCompleted} votes={votes} uploads={uploads} onCat={openCat} onSolo={openSoloPin} onSubmitDraw={()=>{setDrawDone(true);setScreen("draw");}} drawSubmitted={drawDone} onClaimPrizes={()=>setScreen("claimPrizes")}/>}
      {tab==="leaderboard" && <LeaderboardTab currentUser={{...user,id:userId}} currentPoints={points} leaderboard={leaderboard}/>}
      <BottomNav tab={tab} setTab={setTab}/>
    </div>
  );

  if(screen==="category")    return <CategoryScreen cat={activeCat} vendorStamps={vendorStamps} onVendor={openVendorPin} onBack={()=>setScreen("main")}/>;
  if(screen==="pin")         return <PinScreen label={activePin.label} icon={activePin.icon} pin={activePin.pin} hasvote={activePin.hasvote} onSuccess={pinSuccess} onBack={()=>setScreen(activeCat&&activePin?.type==="vendor"?"category":"main")}/>;
  if(screen==="success")     return <SuccessScreen label={lastSuccess.label} icon={lastSuccess.icon} earnedPts={lastSuccess.earnedPts} totalPoints={points} onContinue={()=>setScreen(activeCat&&activePin?.type==="vendor"?"category":"main")}/>;
  if(screen==="claimPrizes") return <ClaimPrizesScreen points={points} onSuccess={claimSuccess} onBack={()=>setScreen("main")}/>;
  if(screen==="prizeClaimed"){
    const prize = getPrize(rawPoints - redeemedPts + (currentPrize?.pts||0) - (currentPrize?.pts||0));
    return <PrizeClaimedScreen prize={currentPrize} remainingPoints={points - (currentPrize?.pts||0)} onContinue={()=>setScreen("main")}/>;
  }
  if(screen==="draw")        return <DrawScreen user={user} points={points} onBack={()=>setScreen("main")}/>;
  return null;
}

